css:
.loader{
  --td-dot: calc(var(--loader-size, 56px) / 5.6);
  --td-gap: calc(var(--loader-size, 56px) / 12);
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:var(--td-gap);
  width:var(--loader-size, 56px);
  height:var(--loader-size, 56px);
}
.loader i{
  width:var(--td-dot);
  height:var(--td-dot);
  border-radius:50%;
  background-color:var(--loader-color, #6366f1);
}
.loader i{animation:td-elastic var(--loader-speed, 1s) infinite linear;transform-origin:center}
.loader i:nth-child(2){animation-delay:calc(var(--loader-speed, 1s) / 4)}
.loader i:nth-child(3){animation-delay:calc(var(--loader-speed, 1s) / 2)}
@keyframes td-elastic{
  0%,100%{transform:scaleY(1)}
  25%{transform:scaleY(1.6)}
  50%{transform:scaleY(0.7)}
  75%{transform:scaleY(1)}
}
